#!/usr/bin/env node
// Build the deck runtime (services/calliope/deck-runtime, vendored bolt-slides)
// and write it into src/lib/server/deck-runtime.generated.ts, so published
// decks carry their runtime inline and render with no network access.
//
// Run after changing the runtime source:
//   node datarabbit/scripts/build-deck-runtime.mjs
// tests/test_deck_runtime_bundle.py fails while the generated file is stale.

import { createHash } from "node:crypto"
import { execFileSync } from "node:child_process"
import fs from "node:fs"
import os from "node:os"
import path from "node:path"
import { fileURLToPath } from "node:url"

const here = path.dirname(fileURLToPath(import.meta.url))
const repo = path.resolve(here, "..", "..")
const runtimeDir = path.join(repo, "services", "calliope", "deck-runtime")
const output = path.join(repo, "datarabbit", "src", "lib", "server", "deck-runtime.generated.ts")

// The same digest tests/test_deck_runtime_bundle.py computes: the runtime's
// source and build configuration, not package.json (release bumps its version).
function sourceDigest() {
  const files = []
  const walk = (dir) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name)
      if (entry.isDirectory()) walk(full)
      else files.push(full)
    }
  }
  walk(path.join(runtimeDir, "src"))
  for (const name of ["vite.config.ts", "tsconfig.json", "tsconfig.node.json"]) {
    const full = path.join(runtimeDir, name)
    if (fs.existsSync(full)) files.push(full)
  }
  const rel = files.map((f) => path.relative(runtimeDir, f).split(path.sep).join("/")).sort()
  const digest = createHash("sha256")
  for (const name of rel) {
    const content = fs.readFileSync(path.join(runtimeDir, name))
    digest.update(`${name}\n${createHash("sha256").update(content).digest("hex")}\n`)
  }
  return digest.digest("hex")
}

const work = fs.mkdtempSync(path.join(os.tmpdir(), "deck-runtime-"))
try {
  fs.cpSync(runtimeDir, work, {
    recursive: true,
    filter: (src) => !/[\\/](node_modules|dist)([\\/]|$)/.test(path.relative(runtimeDir, src)),
  })
  execFileSync("npm", ["ci", "--no-audit", "--no-fund", "--loglevel=error"], { cwd: work, stdio: "inherit" })
  execFileSync("npm", ["run", "build"], { cwd: work, stdio: "inherit" })
  const js = fs.readFileSync(path.join(work, "dist", "deck-runtime.js"), "utf8").replace(/<\/script/gi, "<\\/script")
  const css = fs.readFileSync(path.join(work, "dist", "deck-runtime.css"), "utf8").replace(/<\/style/gi, "<\\/style")
  const text =
    "// Generated by datarabbit/scripts/build-deck-runtime.mjs from services/calliope/deck-runtime.\n" +
    "// Do not edit; rerun the script after changing the runtime source.\n" +
    `export const DECK_RUNTIME_SOURCE_SHA256 = ${JSON.stringify(sourceDigest())}\n` +
    `export const DECK_RUNTIME_CSS = ${JSON.stringify(css)}\n` +
    `export const DECK_RUNTIME_JS = ${JSON.stringify(js)}\n`
  fs.writeFileSync(output, text)
  console.log(`wrote ${path.relative(repo, output)} (${Math.round(text.length / 1024)} KB)`)
} finally {
  fs.rmSync(work, { recursive: true, force: true })
}
